      let g = genGoal(r, dom);
      let pr = ill ? { probes: [] as Probe[], equiv: [] as string[] } : genProbes(r, dom, g);
      for (let k = 0; k < 60 && !ill && !satisfiable(g, pr.probes); k++) { g = genGoal(r, dom); pr = genProbes(r, dom, g); }
      const x = ill ? breakGoal(r, g) : null;
      const goal = x ? x.goal : g;
